// Only missing artwork or content previously generated by Framely may change.
async function(p, id, render, selectPalette) {
    const suffix={0:'p',1:'_hero',2:'_logo',3:'',4:'_icon'};
    const load=data=>new Promise((resolve,reject)=>{const i=new Image(),timer=setTimeout(()=>reject(Error('Artwork decode timeout')),4000);i.onload=()=>{clearTimeout(timer);resolve(i);};i.onerror=()=>{clearTimeout(timer);reject(Error('Invalid artwork'));};i.src=data;});
    const digest=async image=>{
        let c=image;
        if(!image.getContext){c=document.createElement('canvas');c.width=image.width;c.height=image.height;c.getContext('2d').drawImage(image,0,0);}
        const ctx=c.getContext('2d'),pixels=ctx.getImageData(0,0,c.width,c.height).data;
        const header=new TextEncoder().encode(`${c.width}x${c.height}:`),input=new Uint8Array(header.length+pixels.length);input.set(header);input.set(pixels,header.length);
        return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',input))).map(v=>v.toString(16).padStart(2,'0')).join('');
    };
    const inspect=async kind=>{
        const hashes=[];
        for(const ext of ['png','jpg','jpeg','webp']){
            const response=await fetch(`/customimages/${id}${suffix[kind]}.${ext}?framely=${Date.now()}`,{cache:'no-store'});
            if(response.status===404)continue;
            if(!response.ok)throw Error('Cannot inspect existing Steam artwork');
            const blob=await response.blob();
            if(blob.size>16*1024*1024)throw Error('Existing Steam artwork is too large');
            const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob);});
            const image=await load(data);
            if(image.width>8192||image.height>8192||image.width*image.height>16*1024*1024)throw Error('Existing artwork dimensions are too large');
            hashes.push(await digest(image));
        }
        return hashes;
    };
    const owned=p.ownership?.appId===id?p.ownership.hashes:{};
    const hashes={...owned}, generated=await render(p,selectPalette);
    try { for(const a of generated){
        const current=await inspect(a.kind), previous=[];
        if(owned[a.kind])previous.push(owned[a.kind]);
        // One-time upgrade of the exact old plain-background/icon-only images.
        const legacy=p.legacy?.find(v=>v.kind===a.kind);
        if(legacy)previous.push(await digest(await load('data:image/png;base64,'+legacy.data)));
        if(current.length&&current.some(h=>!previous.includes(h))){delete hashes[a.kind];continue;}
        const hash=await digest(a.canvas);
        if(current.length===1&&current[0]===hash){hashes[a.kind]=hash;continue;}
        // Recheck just before writing in case a user changed the image meanwhile.
        const rechecked=await inspect(a.kind);
        if(JSON.stringify(current)!==JSON.stringify(rechecked)){delete hashes[a.kind];continue;}
        try{await SteamClient.Apps.SetCustomArtworkForApp(id,a.data,'png',a.kind);}
        catch(error){await new Promise(r=>setTimeout(r,200));const latest=await inspect(a.kind);if(latest.some(h=>!previous.includes(h)&&h!==hash))throw Error('Steam artwork changed during retry');await SteamClient.Apps.SetCustomArtworkForApp(id,a.data,'png',a.kind);}
        hashes[a.kind]=hash;
    }} catch(error) {
        // Return completed hashes even on a partial failure. The core persists
        // this checkpoint before reporting failure, so retry does not mistake
        // images just written by Framely for user-created artwork.
        return {version:1,appId:id,hashes,failed:true};
    }
    return {version:1,appId:id,hashes};
}
